parameters.jsCode:
/**
 * Normalises the Error Trigger payload into a flat, notification-ready shape.
 *
 * n8n emits TWO different payload shapes and this handles both:
 *   - an execution failed  -> payload.execution  (has id, url, lastNodeExecuted)
 *   - a trigger failed     -> payload.trigger    (no execution id, no url)
 * Reading only payload.execution would silently produce a blank report whenever
 * a polling or schedule trigger is what broke.
 */
const payload = ($input.first() && $input.first().json) || {};
const wf = payload.workflow || {};
const isExecution = !!payload.execution;
const ex = payload.execution || payload.trigger || {};
const err = ex.error || {};

const str = (v) => (v === null || v === undefined) ? '' : String(v);
const clip = (v, n) => {
  const s = str(v);
  return s.length > n ? s.slice(0, n - 3) + '...' : s;
};

// Slack has message size limits and a stack trace can be enormous.
const failedNode = (err.node && err.node.name) || ex.lastNodeExecuted || 'Unknown node';

return [{
  json: {
    workflowName: str(wf.name) || 'Unknown workflow',
    workflowId: str(wf.id),
    failureType: isExecution ? 'EXECUTION' : 'TRIGGER',
    executionId: str(ex.id) || 'n/a (trigger failure)',
    executionUrl: str(ex.url),
    executionMode: str(ex.mode) || 'unknown',
    retryOf: str(ex.retryOf),
    failedNode,
    failedNodeType: str(err.node && err.node.type),
    errorName: str(err.name) || 'Error',
    errorMessage: clip(err.message || err.description || 'No error message reported', 800),
    errorStack: clip(err.stack, 1200),
    occurredAt: new Date().toISOString()
  }
}];

